{"sql":"-- Task 3 Part A: Create the trigger function
drop function if exists check_set_parts_consistency cascade;

CREATE OR REPLACE FUNCTION check_set_parts_consistency()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    relevant_set_num TEXT;
    stored_num_parts INTEGER;
    actual_parts INTEGER;
BEGIN
    -- Determine set_num based on triggering table
    IF TG_TABLE_NAME = 'lego_sets' OR TG_TABLE_NAME = 'lego_inventories' THEN
        relevant_set_num := NEW.set_num;
    ELSIF TG_TABLE_NAME = 'lego_inventory_parts' THEN
        SELECT set_num INTO relevant_set_num FROM lego_inventories WHERE id = NEW.inventory_id;
        IF relevant_set_num IS NULL THEN
            RAISE EXCEPTION 'Inventory id % has no associated set_num', NEW.inventory_id;
        END IF;
    ELSE
        RAISE EXCEPTION 'Trigger fired on unexpected table: %', TG_TABLE_NAME;
    END IF;

    -- Get stored num_parts from lego_sets
    SELECT num_parts INTO stored_num_parts FROM lego_sets WHERE set_num = relevant_set_num;
    IF stored_num_parts IS NULL THEN
        -- If no such set exists in lego_sets, skip check
        RETURN NEW;
    END IF;

    -- Calculate actual parts from latest inventory non-spare parts
    SELECT COALESCE(SUM(lip.quantity), 0) INTO actual_parts
    FROM lego_inventories li
    JOIN lego_inventory_parts lip ON li.id = lip.inventory_id
    WHERE li.set_num = relevant_set_num
    AND lip.is_spare = false
    AND li.version = (
        SELECT MAX(version) FROM lego_inventories WHERE set_num = relevant_set_num
    );

    -- Raise exception if inconsistency found
    IF stored_num_parts <> actual_parts THEN
        RAISE EXCEPTION 'Inconsistent part count for set %: stored = %, actual = %', relevant_set_num, stored_num_parts, actual_parts;
    END IF;

    RETURN NEW;
END;
$$;

-- Task 3 Part B: Create the constraint triggers

DROP TRIGGER IF EXISTS trg_lego_sets_consistency ON public.lego_sets;
CREATE CONSTRAINT TRIGGER trg_lego_sets_consistency
AFTER INSERT OR UPDATE ON public.lego_sets
DEFERRABLE INITIALLY IMMEDIATE
FOR EACH ROW
EXECUTE FUNCTION check_set_parts_consistency();

DROP TRIGGER IF EXISTS trg_lego_inventories_consistency ON public.lego_inventories;
CREATE CONSTRAINT TRIGGER trg_lego_inventories_consistency
AFTER INSERT OR UPDATE ON public.lego_inventories
DEFERRABLE INITIALLY IMMEDIATE
FOR EACH ROW
EXECUTE FUNCTION check_set_parts_consistency();

DROP TRIGGER IF EXISTS trg_lego_inventory_parts_consistency ON public.lego_inventory_parts;
CREATE CONSTRAINT TRIGGER trg_lego_inventory_parts_consistency
AFTER INSERT OR UPDATE ON public.lego_inventory_parts
DEFERRABLE INITIALLY IMMEDIATE
FOR EACH ROW
EXECUTE FUNCTION check_set_parts_consistency();
"}
